<script setup>
import {computed,ref} from 'vue'
import {ThunderboltOutlined,LineChartOutlined,CompassOutlined} from '@ant-design/icons-vue'
import {dimensionSummary} from './classroom.js'
const props=defineProps({students:{type:Array,required:true}})
const expanded=ref(true)
const dimensions=computed(()=>dimensionSummary(props.students))
const completed=computed(()=>props.students.filter(s=>s.complete).length)
const weakest=computed(()=>[...dimensions.value].sort((a,b)=>a.average-b.average)[0])
const strongest=computed(()=>[...dimensions.value].sort((a,b)=>b.average-a.average)[0])
const colors=['#fa4d56','#fa8c16','#22c55e']
const levels=['需關注（<60%）','一般（60–79%）','優異（≥80%）']
function point(index,value){const axes=[[0,-1],[-1,0],[0,1],[1,0]];return `${160+axes[index][0]*value},${150+axes[index][1]*value}`}
const polygon=computed(()=>dimensions.value.map((d,i)=>point(i,d.average)).join(' '))
</script>
<template>
<section class="class-ai"><button class="overview-ai" :aria-expanded="expanded" @click="expanded=!expanded"><ThunderboltOutlined/> AI 智能總結 <span class="ai-toggle">{{expanded?'收起':'展開'}}</span></button><div v-if="expanded" class="ai-copy"><template v-if="completed">已完成 {{completed}} / {{students.length}} 人。班級「{{strongest.name}}」平均得分率最高（{{strongest.average.toFixed(1)}}%）；「{{weakest.name}}」平均得分率為 {{weakest.average.toFixed(1)}}%，其中 {{weakest.counts[0]}} 人需關注。建議優先安排{{weakest.name}}專項練習，結合作文例子講解，並追蹤修改後的表現。</template><template v-else>暫無已完成評分，完成批改後生成班級分析。</template></div></section>
<section class="overview-analysis restored-analysis"><div class="analysis-tab"><LineChartOutlined/> 薄弱點分析</div><div class="restored-body"><div class="radar-panel"><h2><LineChartOutlined/> 評分維度分析</h2><svg viewBox="0 0 320 300" role="img" :aria-label="'班級四維平均得分率：'+dimensions.map(d=>d.name+d.average.toFixed(1)+'%').join('、')"><polygon v-for="r in [20,40,60,80,100]" :key="r" :points="[0,1,2,3].map(i=>point(i,r)).join(' ')" fill="none" stroke="#e5eaf2"/><line v-for="i in [0,1,2,3]" :key="i" x1="160" y1="150" :x2="point(i,100).split(',')[0]" :y2="point(i,100).split(',')[1]" stroke="#e5eaf2"/><polygon :points="polygon" fill="#3973ff26" stroke="#3973ff" stroke-width="2"/><g v-for="(d,i) in dimensions" :key="d.name"><circle :cx="point(i,d.average).split(',')[0]" :cy="point(i,d.average).split(',')[1]" r="3" fill="#3973ff"/><text :x="[160,32,160,283][i]" :y="[23,150,278,150][i]" text-anchor="middle" fill="#65758a" font-size="11">{{d.name}}</text><text :x="[160,32,160,283][i]" :y="[39,167,294,167][i]" text-anchor="middle" fill="#3973ff" font-size="10">{{d.average.toFixed(1)}}%</text></g></svg><p>已完成學生的平均得分率</p></div><div class="dimension-panel"><div class="dimension-heading"><h2><CompassOutlined/> 維度得分詳情</h2><div class="dimension-legend"><span v-for="(level,i) in levels" :key="level"><i :style="{background:colors[i]}"/>{{level}}</span></div></div><article v-for="d in dimensions" :key="d.name" class="dimension-row"><div><b>{{d.name}}</b><span class="dimension-average">平均：{{d.average.toFixed(1)}}%</span></div><div class="dimension-stack"><i v-for="(count,i) in d.counts" :key="i" :style="{width:(completed?count/completed*100:0)+'%',background:colors[i]}" :title="levels[i]+'：'+count+'人'"/></div><div class="dimension-counts"><span v-for="(count,i) in d.counts" :key="i"><i :style="{background:colors[i]}"/>{{count}}人</span></div></article><p class="dimension-footnote">未完成 {{students.length-completed}} 人不計入分析；各維度按自身滿分計算得分率。</p></div></div></section>
</template>
<style scoped>
.class-ai{margin:12px 0;background:#eff6ff;border:1px solid #dce9ff;border-radius:14px;overflow:hidden}.class-ai .overview-ai{margin:0;border:0;border-radius:0}.demo-label{font-size:10px;color:#8194b2;font-weight:400}.ai-toggle{margin-left:auto;font-size:11px}.ai-copy{padding:0 16px 15px;color:#526b8f;font-size:12px;line-height:1.9}.restored-body{display:grid;grid-template-columns:minmax(240px,1fr) 2fr;padding:16px;gap:20px}.restored-body h2{font-size:12px;font-weight:600;margin:0 0 12px}.radar-panel{border-right:1px solid #edf0f5;padding-right:16px}.radar-panel svg{display:block;width:100%;max-height:300px}.radar-panel p,.dimension-footnote{font-size:10px;color:#8b98a9;margin:8px 0}.radar-panel p{text-align:center}.dimension-heading{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}.dimension-legend{display:flex;gap:10px;font-size:10px;color:#7b8ba1;margin-bottom:12px}.dimension-legend i,.dimension-counts i{display:inline-block;width:6px;height:6px;border-radius:50%;margin-right:4px}.dimension-row{background:#f7f9fc;border-radius:10px;padding:12px;margin-bottom:10px;font-size:11px}.dimension-average{margin-left:8px;padding:3px 6px;background:#eaf0ff;border-radius:4px;color:#3973ff;font-size:10px}.dimension-stack{display:flex;height:7px;margin:13px 0 7px;background:#edf0f5;border-radius:7px;overflow:hidden}.dimension-stack i{height:100%}.dimension-counts{display:flex;justify-content:space-between;color:#7b8ba1;font-size:10px}@media(max-width:900px){.restored-body{grid-template-columns:1fr}.radar-panel{border:0;padding:0}.dimension-legend{flex-wrap:wrap}}
</style>
